35	#define SATP_MODE_SV48 9
36	#define SATP_ASID_SHIFT 44lu
37	#define SATP_MODE_SHIFT 60lu
38	
39	static inline void set_satp(
40	    unsigned mode, unsigned asid, unsigned long ppn)
41	{
42	    unsigned long __v =
43	        (unsigned long)(((unsigned long)mode << SATP_MODE_SHIFT) | ((unsigned long)asid << SATP_ASID_SHIFT) | ppn);
44	    __asm__ __volatile__("sfence.vma\ncsrw satp, %0" : : "rK"(__v) : "memory");
45	}
