241	    enable_interrupt();
242	    setup_exception();
243	    sbi_set_timer(get_ticks() + timer_interval);
244	
245	    while (1){
246	        disable_preempt();
247	        list_node_t* clean_node = kernel_pcb[0].wait_list.next;
248	        while(clean_node != &kernel_pcb[0].wait_list){
249	            pcb_t *clean_pcb = list_entry(clean_node, pcb_t, list);
250	            // release pcb
251	            clean_pcb->status = TASK_EXITED;
252	            clean_pcb->pid = -1;
253	            // release kernel stack
254	            free_user_page(kva2pa(clean_pcb->kernel_stack_base - PAGE_SIZE));
255	            
256	            clean_node = clean_node->next;
257	            list_del(clean_node->prev);
258	        }
259	    
260	        enable_preempt();
261	        __asm__ __volatile__("wfi\n\r":::);
262	    }
