```c
PTE* init_page_table()
{
    PTE *pgdir = alloc_pgdir_page();
    // copy kernel mapping (share the kernel second-level table)
    PTE *boot_pgdir = (PTE*)pa2kva(PGDIR_PA);
    PTE *pgdir_kva = (PTE*)pa2kva((uintptr_t)pgdir);
    pgdir_kva[0x001] = boot_pgdir[0x001];
    pgdir_kva[0x101] = boot_pgdir[0x101];
    // map user stack
    alloc_page_helper(USER_STACK_ADDR - PAGE_SIZE, (uintptr_t)pgdir);
    return pgdir;
}
```

