// returns pa
ptr_t alloc_user_page(uint8_t pin, PTE* pgtable)
{
    int i;
    for(i = 0; i < USER_PAGE_NUM; i++){
        if(user_page[i].valid == 0){
            break;
        }
    }
    if(i == USER_PAGE_NUM){
        // no free user page: swap out a victim page to sd
        ptr_t victim_pa = selete_page();
        write_to_sd(victim_pa);
        i = pa2num(victim_pa);
    }
    user_page[i].valid = 1;
    user_page[i].pin = pin;
    user_page[i].pgtable = pgtable;
    return num2pa(i);
}

// select a user page to write to disk (NRU), returns pa
ptr_t selete_page()
{
    int i;
    // first round: pick a valid unpinned page whose A bit is 0,
    // clearing the A bit of the pages we skip (second chance)
    for(i = 0; i < USER_PAGE_NUM; i++){
        if(user_page[i].valid && !user_page[i].pin){
            PTE *pte = user_page[i].pgtable;
            if(pte != NULL && get_attribute(*pte, _PAGE_ACCESSED)){
                clear_attribute(pte, _PAGE_ACCESSED);
            }
            else{
                return num2pa(i);
            }
        }
    }
    // second round: all A bits were cleared, pick the first victim
    for(i = 0; i < USER_PAGE_NUM; i++){
        if(user_page[i].valid && !user_page[i].pin){
            return num2pa(i);
        }
    }
    // every user page is pinned: should not happen
    assert(0);
    return 0;
}

void write_to_sd(ptr_t pa)
{
    // find a free swap slot on sd
    int i;
    for(i = 0; i < DISK_PAGE_NUM; i++){
        if(disk_page[i].valid == 0){
            break;
        }
    }
    assert(i != DISK_PAGE_NUM);
    disk_page[i].valid = 1;

    // a page occupies PAGE_SIZE / 512 blocks, swap area starts at SWAP_BEGIN
    sbi_sd_write(pa, PAGE_SIZE / 512, SWAP_BEGIN + i * (PAGE_SIZE / 512));

    // mark the owner's PTE as swapped out: !PRESENT, SOFT set,
    // and record the swap slot index in the pfn field
    int num = pa2num(pa);
    PTE *pte = user_page[num].pgtable;
    clear_attribute(pte, _PAGE_PRESENT);
    set_attribute(pte, _PAGE_SOFT);
    set_pfn(pte, i);

    user_page[num].valid = 0;
    local_flush_tlb_all();
}

