PTE* init_page_table()
{
    // allocate a fresh top level page table, returns pa
    PTE *pgdir = alloc_pgdir_page();
    PTE *pgdir_kva = (PTE*)pa2kva((uintptr_t)pgdir);
    PTE *boot_pgdir_kva = (PTE*)pa2kva(PGDIR_PA);

    /*
     * share the kernel mappings with the boot page table:
     * entry 0x001: identity map of 0x5000_0000 ~ 0x6000_0000 (large pages)
     * entry 0x101: kernel virtual map (large pages)
     * both point to the shared second level table at PGDIR_PA + PAGE_SIZE,
     * so trap handling and kernel code stay reachable under every satp
     */
    pgdir_kva[0x001] = boot_pgdir_kva[0x001];
    pgdir_kva[0x101] = boot_pgdir_kva[0x101];

    // map one page for the user stack: [USER_STACK_ADDR - PAGE_SIZE, USER_STACK_ADDR)
    alloc_page_helper(USER_STACK_ADDR - PAGE_SIZE, (uintptr_t)pgdir);

    return pgdir;
}

void free_process_user_page(PTE* pgdir)
{
    PTE *pgdir_kva = (PTE*)pa2kva((uintptr_t)pgdir);
    for(int VPN2 = 0; VPN2 < NUM_PTE_ENTRY; VPN2++){
        // entries 0x001/0x101 reference the shared kernel table: never touch
        if(VPN2 == 0x001 || VPN2 == 0x101){
            continue;
        }
        if(!get_attribute(pgdir_kva[VPN2], _PAGE_PRESENT)){
            continue;
        }
        PTE *second_level_pgdir = (PTE*)pa2kva(get_pa(pgdir_kva[VPN2]));
        for(int VPN1 = 0; VPN1 < NUM_PTE_ENTRY; VPN1++){
            if(!get_attribute(second_level_pgdir[VPN1], _PAGE_PRESENT)){
                continue;
            }
            PTE *last_level_pgdir = (PTE*)pa2kva(get_pa(second_level_pgdir[VPN1]));
            for(int VPN0 = 0; VPN0 < NUM_PTE_ENTRY; VPN0++){
                PTE entry = last_level_pgdir[VPN0];
                if(get_attribute(entry, _PAGE_PRESENT)){
                    uintptr_t pa = get_pa(entry);
                    // a shared memory page is only released when its
                    // reference count drops to zero
                    int is_shm = 0;
                    for(int i = 0; i < SHM_PAGE_NUM; i++){
                        if(shm_page[i].count > 0 && shm_page[i].pa == pa){
                            shm_page[i].count--;
                            if(shm_page[i].count == 0){
                                free_user_page(pa);
                            }
                            is_shm = 1;
                            break;
                        }
                    }
                    if(!is_shm){
                        free_user_page(pa);
                    }
                }
                else if(get_attribute(entry, _PAGE_SOFT)){
                    // swapped out page: release its swap slot on sd
                    disk_page[get_pfn(entry)].valid = 0;
                }
            }
            // free the last level page table itself
            free_pgdir_page(get_pa(second_level_pgdir[VPN1]));
        }
        // free the second level page table itself
        free_pgdir_page(get_pa(pgdir_kva[VPN2]));
    }
    local_flush_tlb_all();
}

// pgdir is pa. if va is not mapped, then mapped it
uintptr_t alloc_page_helper(uintptr_t va, uintptr_t pgdir)
{
    int VPN2 = (va >> VPN2_SHIFT) & VPN_MASK;
    int VPN1 = (va >> VPN1_SHIFT) & VPN_MASK;
    int VPN0 = (va >> VPN0_SHIFT) & VPN_MASK;

    PTE *pgdir_kva = (PTE*)pa2kva(pgdir);
    if(!get_attribute(pgdir_kva[VPN2], _PAGE_PRESENT)){
        PTE *second_level_pgdir = alloc_pgdir_page();
        set_pfn(&pgdir_kva[VPN2], (uintptr_t)second_level_pgdir >> NORMAL_PAGE_SHIFT);
        set_attribute(&pgdir_kva[VPN2], _PAGE_PRESENT);
    }

    PTE *second_level_pgdir = (PTE*)pa2kva(get_pa(pgdir_kva[VPN2]));
    if(!get_attribute(second_level_pgdir[VPN1], _PAGE_PRESENT)){
        PTE *last_level_pgdir = alloc_pgdir_page();
        set_pfn(&second_level_pgdir[VPN1], (uintptr_t)last_level_pgdir >> NORMAL_PAGE_SHIFT);
        set_attribute(&second_level_pgdir[VPN1], _PAGE_PRESENT);
    }

    PTE *last_level_pgdir = (PTE*)pa2kva(get_pa(second_level_pgdir[VPN1]));
    if(!get_attribute(last_level_pgdir[VPN0], _PAGE_PRESENT)){
        ptr_t pa = alloc_user_page(0, &last_level_pgdir[VPN0]);
        set_pfn(&last_level_pgdir[VPN0], pa >> NORMAL_PAGE_SHIFT);
        set_attribute(&last_level_pgdir[VPN0], _PAGE_PRESENT);
        set_attribute(&last_level_pgdir[VPN0], _PAGE_READ);
        set_attribute(&last_level_pgdir[VPN0], _PAGE_WRITE);
        set_attribute(&last_level_pgdir[VPN0], _PAGE_EXEC);
        set_attribute(&last_level_pgdir[VPN0], _PAGE_USER);
        set_attribute(&last_level_pgdir[VPN0], _PAGE_ACCESSED);
        set_attribute(&last_level_pgdir[VPN0], _PAGE_DIRTY);
    }

    return pa2kva(get_pa(last_level_pgdir[VPN0])) | (va & PAGE_OFFSET_MASK);
}

