    set_attribute(pte, _PAGE_PRESENT);
    set_attribute(pte, _PAGE_READ);
    set_attribute(pte, _PAGE_WRITE);
    set_attribute(pte, _PAGE_USER);
    set_attribute(pte, _PAGE_ACCESSED);
    set_attribute(pte, _PAGE_DIRTY);
    local_flush_tlb_all();

    return va;
}

void shm_page_dt(uintptr_t addr)
{
    pcb_t *cur = current_running[cpu_id];
    PTE *pte = walk_pgdir(addr, (uintptr_t)cur->pgdir);
    if(pte == NULL || !get_attribute(*pte, _PAGE_PRESENT)){
        return;
    }

    uintptr_t pa = get_pa(*pte);
    for(int i = 0; i < SHM_PAGE_NUM; i++){
        if(shm_page[i].count > 0 && shm_page[i].pa == pa){
            shm_page[i].count--;
            if(shm_page[i].count == 0){
                free_user_page(pa);
            }
            break;
        }
    }

    // unmap the page from the current address space
    *pte = 0;
    local_flush_tlb_all();
}

void handle_page_fault(regs_context_t *regs, uint64_t stval, uint64_t cause)
{
    pcb_t *cur = current_running[cpu_id];
    uintptr_t va = stval;
    PTE *pte = walk_pgdir(va, (uintptr_t)cur->pgdir);

    if(pte != NULL && get_attribute(*pte, _PAGE_SOFT)){
        // the page was swapped out to sd: swap it back in
        int slot = get_pfn(*pte);
        ptr_t pa = alloc_user_page(0, pte);
        sbi_sd_read(pa, PAGE_SIZE / 512, SWAP_BEGIN + slot * (PAGE_SIZE / 512));
        disk_page[slot].valid = 0;

        clear_attribute(pte, _PAGE_SOFT);
        set_pfn(pte, pa >> NORMAL_PAGE_SHIFT);
        set_attribute(pte, _PAGE_PRESENT);
        set_attribute(pte, _PAGE_ACCESSED);
    }
    else if(pte == NULL || !get_attribute(*pte, _PAGE_PRESENT)){
        // the page has never been mapped: demand paging
        alloc_page_helper(va, (uintptr_t)cur->pgdir);
    }
    local_flush_tlb_all();
}

