    release_all_binsem(kill_pcb);

    // wake up the processes waiting for it
    while(!list_empty(&kill_pcb->wait_list)){
        do_unblock(kill_pcb->wait_list.next);
    }

    // remove it from whatever queue it is in
    list_del(&kill_pcb->list);

    // release the vm resources
    free_process_user_page(kill_pcb->pgdir);
    free_pgdir_page((uintptr_t)kill_pcb->pgdir);
    kill_pcb->pgdir = NULL;

    // let the kernel idle loop recycle the pcb and kernel stack
    kill_pcb->status = TASK_ZOMBIE;
    list_add_tail(&kill_pcb->list, &kernel_pcb[0].wait_list);

    return 1;
}

int do_waitpid(pid_t pid, reg_t ignore1, reg_t ignore2, reg_t ignore3, regs_context_t *regs)
{
    // search the pcb
    pcb_t *wait_pcb = NULL;
    for(int i = 0; i < NUM_MAX_TASK; i++){
        if(pcb[i].pid == pid){
            wait_pcb = &pcb[i];
            break;
        }
    }
    if(wait_pcb == NULL || wait_pcb->status == TASK_EXITED){
        return 0;
    }

    if(wait_pcb->status != TASK_ZOMBIE){
        // block until the target process exits
        do_block(&current_running[cpu_id]->list, &wait_pcb->wait_list);
        scheduler();
    }

    // recycle the zombie: release its vm resources (unless they were
    // already released by an AUTO_CLEANUP_ON_EXIT do_exit/do_kill) and
    // hand the pcb and kernel stack to the kernel idle loop
    if(wait_pcb->pgdir != NULL){
        free_process_user_page(wait_pcb->pgdir);
        free_pgdir_page((uintptr_t)wait_pcb->pgdir);
        wait_pcb->pgdir = NULL;
        list_del(&wait_pcb->list);
        list_add_tail(&wait_pcb->list, &kernel_pcb[0].wait_list);
    }

    return pid;
}

