list_node_t* max_priority_node(void)
{
    list_node_t *node = ready_queue.next;
    list_node_t *max_node = NULL;
    while(node != &ready_queue){
        pcb_t *p = list_entry(node, pcb_t, list);
        // skip dead processes and processes pinned to the other core
        if(p->pgdir != NULL && (p->mask & (1lu << cpu_id))){
            if(max_node == NULL){
                max_node = node;
            }
            else{
                pcb_t *max_pcb = list_entry(max_node, pcb_t, list);
                // higher priority first; break ties by the earliest ready_tick
                if(p->priority > max_pcb->priority ||
                   (p->priority == max_pcb->priority && p->ready_tick < max_pcb->ready_tick)){
                    max_node = node;
                }
            }
        }
        node = node->next;
    }
    return max_node;
}

